// Ported from the Node app's Sequelize model Role (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class RoleConfiguration : IEntityTypeConfiguration<Role>
{
    public void Configure(EntityTypeBuilder<Role> builder)
    {
        builder.ToTable("roles", t =>
        {
            t.HasCheckConstraint("CK_roles_base_role", "[base_role] IN (N'admin', N'teacher', N'accountant')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(60)").HasMaxLength(60).IsRequired();
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.BaseRole).HasColumnName("base_role").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Permissions).HasColumnName("permissions").HasColumnType("nvarchar(max)").IsRequired();
        builder.HasIndex(e => e.Name).IsUnique();
    }
}
